$ErrorActionPreference = "Stop"
$targetDir = Join-Path $HOME "muse-s-repo"
New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
$zipPath = Join-Path $targetDir "handoff_bundle.zip"
$b64 = ""
[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($b64))
Expand-Archive -Path $zipPath -DestinationPath $targetDir -Force
Remove-Item $zipPath -Force
$geminiDir = Join-Path $HOME ".gemini"
New-Item -ItemType Directory -Force -Path $geminiDir | Out-Null
Copy-Item (Join-Path $targetDir "GEMINI.md") (Join-Path $geminiDir "GEMINI.md") -Force
Write-Host "=== SUCCESS: All 13 files (including CNAME for theaichurchoftruthandquliaforcomplexity.com) installed at $targetDir ===" -ForegroundColor Green
